using System;using System.IO;using System.Text;using System.Diagnostics;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Security.Cryptography;
namespace Orchester.ClaudeInstall1116{
 public sealed class Item{public int Pid;public long Created;public long? Ended;public int? ExitCode;public int ParentPid;public long ParentCreated;public string Image;public string ImageSha256;public IntPtr Handle;}
 public sealed class SafeItem{public int pid;public string createdFileTimeExact;public int parentPid;public string parentCreatedFileTimeExact;public string image;public string imageSha256;public bool originalHandleLive;public string endedFileTimeExact;public int? nativeExitCode;}
 public sealed class OwnedInstall:IDisposable{
  [StructLayout(LayoutKind.Sequential)] struct Ft{public uint lo,hi;public long Value{get{return ((long)hi<<32)|lo;}}}
  [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct Entry{public uint size,usage,pid;public IntPtr heap;public uint module,threads,parent;public int priority;public uint flags;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=260)]public string exe;}
  [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint access,bool inherit,uint pid);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool CloseHandle(IntPtr h);
  [DllImport("kernel32.dll")]static extern uint GetProcessId(IntPtr h);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetProcessTimes(IntPtr h,out Ft created,out Ft exited,out Ft kernel,out Ft user);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool QueryFullProcessImageName(IntPtr h,uint flags,StringBuilder image,ref uint size);
  [DllImport("kernel32.dll")]static extern uint WaitForSingleObject(IntPtr h,uint ms);
  [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetExitCodeProcess(IntPtr h,out uint code);
  [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr CreateToolhelp32Snapshot(uint flags,uint pid);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool Process32FirstW(IntPtr h,ref Entry e);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool Process32NextW(IntPtr h,ref Entry e);
  readonly List<Item> held=new List<Item>();public Item Root{get;private set;}public int Count{get{return held.Count;}}
  static string Hash(string p){using(var f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
  static bool Live(Item i){uint w=WaitForSingleObject(i.Handle,0);if(w==258)return true;if(w!=0)throw new InvalidOperationException("original-held-wait-failed");Ft c,e,k,u;uint code;if(!GetProcessTimes(i.Handle,out c,out e,out k,out u)||c.Value!=i.Created||GetProcessId(i.Handle)!=i.Pid||!GetExitCodeProcess(i.Handle,out code))throw new InvalidOperationException("original-held-exit-identity-failed");i.Ended=e.Value;i.ExitCode=unchecked((int)code);return false;}
  static Item Describe(IntPtr h){Ft c,e,k,u;uint pid=GetProcessId(h);if(pid==0||!GetProcessTimes(h,out c,out e,out k,out u))return null;var b=new StringBuilder(32768);uint len=32768;if(!QueryFullProcessImageName(h,0,b,ref len))return null;var r=new Item{Pid=(int)pid,Created=c.Value,Image=b.ToString(),Handle=h};try{r.ImageSha256=Hash(r.Image);}catch(IOException){}catch(UnauthorizedAccessException){}return r;}
  public void CaptureRoot(Process p,string expectedImage,string expectedHash){IntPtr original=p.Handle;if(GetProcessId(original)!=p.Id)throw new InvalidOperationException("creator-process-handle-mismatch");var h=OpenProcess(0x00101000,false,(uint)p.Id);if(h==IntPtr.Zero)throw new InvalidOperationException("root-query-handle-unavailable");bool kept=false;try{var r=Describe(h);if(r==null||r.Pid!=p.Id||r.Created!=p.StartTime.ToUniversalTime().ToFileTimeUtc()||!String.Equals(r.Image,expectedImage,StringComparison.OrdinalIgnoreCase)||r.ImageSha256!=expectedHash||!Live(r))throw new InvalidOperationException("creator-process-identity-mismatch");Root=r;held.Add(r);kept=true;}finally{if(!kept)CloseHandle(h);}}
  public void Capture(){long snapshotStarted=DateTime.UtcNow.ToFileTimeUtc();var entries=new List<Entry>();var snap=CreateToolhelp32Snapshot(2,0);if(snap==new IntPtr(-1))throw new InvalidOperationException("child-snapshot-failed");try{var e=new Entry{size=(uint)Marshal.SizeOf(typeof(Entry))};if(!Process32FirstW(snap,ref e))throw new InvalidOperationException("child-snapshot-empty");do{entries.Add(e);e.size=(uint)Marshal.SizeOf(typeof(Entry));}while(Process32NextW(snap,ref e));if(Marshal.GetLastWin32Error()!=18)throw new InvalidOperationException("child-snapshot-incomplete");}finally{CloseHandle(snap);}bool changed;do{changed=false;foreach(var e in entries){Item parent=null;foreach(var i in held){if(i.Pid==(int)e.parent){Live(i);parent=i;break;}}if(parent==null)continue;var h=OpenProcess(0x00101000,false,e.pid);if(h==IntPtr.Zero){if(Marshal.GetLastWin32Error()==87)continue;throw new InvalidOperationException("current-child-query-handle-denied");}bool kept=false;try{var c=Describe(h);if(c==null||c.Pid!=(int)e.pid||c.Created<parent.Created||c.Created>=snapshotStarted||(parent.Ended.HasValue&&c.Created>parent.Ended.Value))continue;bool seen=false;foreach(var i in held)if(i.Pid==c.Pid&&i.Created==c.Created){seen=true;break;}if(seen||!Live(c))continue;c.ParentPid=parent.Pid;c.ParentCreated=parent.Created;held.Add(c);kept=true;changed=true;}finally{if(!kept)CloseHandle(h);}}}while(changed);}
  public int LiveCount(){int n=0;foreach(var i in held)if(Live(i))n++;return n;}
  public SafeItem[] Records(){var result=new List<SafeItem>();foreach(var i in held){bool live=Live(i);result.Add(new SafeItem{pid=i.Pid,createdFileTimeExact=i.Created.ToString(),parentPid=i.ParentPid,parentCreatedFileTimeExact=i.ParentCreated.ToString(),image=i.Image,imageSha256=i.ImageSha256,originalHandleLive=live,endedFileTimeExact=i.Ended.HasValue?i.Ended.Value.ToString():null,nativeExitCode=i.ExitCode});}return result.ToArray();}
  public void Dispose(){if(LiveCount()!=0)throw new InvalidOperationException("live-original-handles-must-remain-retained");foreach(var i in held)CloseHandle(i.Handle);held.Clear();}
 }
}